// Package grpcadapt adapts the db and finalize packages to the consumer-side
// interfaces of grpcapi (grpcapi.Repo and grpcapi.Finalizer).
//
// Identity: the gRPC upload_id is the uploads row's upload_ref. The row's
// primary key id is generated by db.Repo and never leaves this package, so
// grpcapi.Upload.ID always holds upload_ref.
package grpcadapt

import (
	"context"
	"errors"
	"fmt"
	"io"

	"github.com/resyahrial/sensor-upload-server/internal/db"
	"github.com/resyahrial/sensor-upload-server/internal/finalize"
	"github.com/resyahrial/sensor-upload-server/internal/grpcapi"
)

// Repo implements grpcapi.Repo on top of *db.Repo, restricted to protocol
// 'grpc' rows.
type Repo struct {
	db *db.Repo
}

var _ grpcapi.Repo = (*Repo)(nil)

// NewRepo returns a Repo using r.
func NewRepo(r *db.Repo) *Repo { return &Repo{db: r} }

// Insert stores a new 'uploading' row with upload_ref = u.ID. u.Status,
// u.Committed and u.CreatedAt are ignored: the database sets them.
func (r *Repo) Insert(ctx context.Context, u grpcapi.Upload) error {
	if _, err := r.db.InsertUploading(ctx, grpcapi.Protocol, u.ID, u.Meta); err != nil {
		return err
	}
	return nil
}

// Get returns the grpc row with upload_ref id, in any status.
func (r *Repo) Get(ctx context.Context, id string) (grpcapi.Upload, error) {
	u, err := r.db.Get(ctx, grpcapi.Protocol, id)
	if err != nil {
		return grpcapi.Upload{}, mapErr(err)
	}
	return toUpload(u), nil
}

// CompletedExists reports whether a row of any protocol with this sha256 is
// completed.
func (r *Repo) CompletedExists(ctx context.Context, sha256 string) (bool, error) {
	_, err := r.db.FindCompletedBySHA(ctx, sha256)
	switch {
	case err == nil:
		return true, nil
	case errors.Is(err, db.ErrNotFound):
		return false, nil
	default:
		return false, err
	}
}

// FindInProgress returns the most recent 'uploading' grpc row for sha256 and
// deviceID.
func (r *Repo) FindInProgress(ctx context.Context, sha256, deviceID string) (grpcapi.Upload, error) {
	u, err := r.db.FindInProgress(ctx, sha256, deviceID, grpcapi.Protocol)
	if err != nil {
		return grpcapi.Upload{}, mapErr(err)
	}
	return toUpload(u), nil
}

// UpdateCommitted sets committed_bytes of an 'uploading' row.
func (r *Repo) UpdateCommitted(ctx context.Context, id string, committed int64) error {
	return mapErr(r.db.UpdateCommitted(ctx, grpcapi.Protocol, id, committed))
}

// IncrementResumes adds one to resume_count of an 'uploading' row.
func (r *Repo) IncrementResumes(ctx context.Context, id string) error {
	return mapErr(r.db.IncrResume(ctx, grpcapi.Protocol, id))
}

// MarkCancelled moves an 'uploading' row to 'cancelled'.
func (r *Repo) MarkCancelled(ctx context.Context, id string) error {
	return mapErr(r.db.SetStatus(ctx, grpcapi.Protocol, id, db.StatusCancelled))
}

// mapErr wraps db.ErrNotFound and db.ErrNotUploading with grpcapi.ErrNotFound
// (the row is not, or no longer, a usable in-progress upload), keeping the
// original error in the chain.
func mapErr(err error) error {
	if errors.Is(err, db.ErrNotFound) || errors.Is(err, db.ErrNotUploading) {
		return fmt.Errorf("%w: %w", grpcapi.ErrNotFound, err)
	}
	return err
}

func toUpload(u db.Upload) grpcapi.Upload {
	return grpcapi.Upload{
		ID:        u.Ref,
		Meta:      u.Metadata(),
		Committed: u.CommittedBytes,
		Status:    string(u.Status),
		CreatedAt: u.CreatedAt,
	}
}

// Finalizer implements grpcapi.Finalizer on top of *finalize.Finalizer. The
// finalizer emits the completed/failed/finalize/duration metrics itself.
type Finalizer struct {
	f *finalize.Finalizer
}

var _ grpcapi.Finalizer = (*Finalizer)(nil)

// NewFinalizer returns a Finalizer using f.
func NewFinalizer(f *finalize.Finalizer) *Finalizer { return &Finalizer{f: f} }

// Run finalizes the upload in.Ref. finalize.ErrChecksum is wrapped with
// grpcapi.ErrChecksumMismatch, finalize.ErrDuplicate with
// grpcapi.ErrDuplicate, and finalize.ErrInactive (cancelled or expired
// meanwhile) or an unknown row with grpcapi.ErrNotFound. Other errors are
// transient and returned as they are.
func (a *Finalizer) Run(ctx context.Context, in grpcapi.FinalizeInput) error {
	_, err := a.f.Run(ctx, finalize.Input{
		Protocol: in.Protocol,
		Ref:      in.Ref,
		Open:     func(context.Context) (io.ReadCloser, error) { return in.Open() },
		Delete:   func(context.Context) error { return in.Delete() },
	})
	switch {
	case err == nil:
		return nil
	case errors.Is(err, finalize.ErrChecksum):
		return fmt.Errorf("%w: %w", grpcapi.ErrChecksumMismatch, err)
	case errors.Is(err, finalize.ErrDuplicate):
		return fmt.Errorf("%w: %w", grpcapi.ErrDuplicate, err)
	case errors.Is(err, finalize.ErrInactive), errors.Is(err, db.ErrNotFound):
		return fmt.Errorf("%w: %w", grpcapi.ErrNotFound, err)
	default:
		return fmt.Errorf("finalize: %w", err)
	}
}
